rules.pseudocode:
// written for the SHORT, as the note states it; the long side is the mirror
if (ctx.MarketPosition() >= 0) return false;
sig = ctx.BarsSinceEntry() + 1;                      // the signal bar, one bar before the entry bar
breakoutPoint = highest(high, X)[sig + 1];           // prior X-bar high as of the signal bar
return low[0] < breakoutPoint;

for (k = 1; k <= maxWaitBars; ++k) {
  if (!(ConsolidationZone(lag = k + 1) && ConsolidationBreakoutBar at offset k)) continue;   // most recent breakout
  zh = highest(high, X)[k + 1]; zl = lowest(low, X)[k + 1];
  if (any j in 1..k-1 with low[j] <= zh) return false;   // an earlier bar already came back: not the first
  return low[0] <= zh && low[0] >= zl && close[0] > zh;
}
return false;

for (k = 1; k <= maxWaitBars; ++k) {
  if (!(ConsolidationZone(lag = k + 1) && ConsolidationBreakoutBar at offset k)) continue;   // most recent breakout
  if (any j in 1..k-1 with close[j] > high[k]) return false;
  return close[0] > high[k];
}
return false;

cls(j): up = high[j] > highest(high, N)[j+1]; dn = low[j] < lowest(low, N)[j+1];
        H if close[j] > highest(high, N)[j+1]; L if close[j] < lowest(low, N)[j+1]; C if (up || dn) && neither; else NONE;
if (cls(0) != H) return false;
nC = 0;
for (j = 1; j <= maxSpan; ++j) {
  c = cls(j);
  if (c == NONE) continue;          // non-breakout bars skipped (open question)
  if (c == C) { ++nC; continue; }
  return c == H && nC >= minC;     // first non-C breakout candle closes the pattern
}
return false;

up = 0; seen = 0;
for (i = 0; i < maxScanBars && seen < Y; ++i) {
    u = el_gt(high[i], highest(high, X)[i + 1]);
    d = el_lt(low[i], lowest(low, X)[i + 1]);
    if (u && !d) { up = up + 1; seen = seen + 1; }
    else if (d && !u) { seen = seen + 1; }
}
long = seen == Y && el_ge(up, F * Y);

cnt = 0;
for (i = 0; i < X; ++i) if (el_ge(high[i], highest(high, Y)[i])) cnt = cnt + 1;   // bar i is the high of the Y bars ending at it
long = el_ge(cnt, fraction * X);

hh = highest(high, X)[1]; ll = lowest(low, X)[1];
out = maxlist(high[0] - hh, 0) + maxlist(ll - low[0], 0);
pass = el_ge(out, T * (high[0] - low[0]));   // product form: a zero-range bar cannot divide by zero
